/**
 * Golden fixtures for the in-app costing maths: ChatGPT's TypeScript port, lib/costing/engine.ts (branch chatgpt/costing-in-tolra),
 * calcDetailedQuote(DetailedInputs) returning the Python engine's to_dict() shape. tests/fixtures/costing-golden.json was generated by
 * running the REAL Python engine (calc_detailed_quote and to_dict in services/costing-engine/app/services/quoting_enhanced.py on
 * claude/a8-costing-activation 9b98c3f, CPython 3.13) on fixed inputs: every operation shape and optional key, quantities 1 to 1000,
 * scrap, margins 0 to 95%, overhead multipliers, and each tooling, tool-change, in-process inspection, consumables, programming and
 * first-article branch. For every case the port must give exactly to_dict()'s values (to the penny, the same float, Object.is).
 * Python's round(x, n) rounds the float's exact binary value with ties to EVEN (21.125 -> 21.12, 1.125 -> 1.12): py_round holds
 * CPython's answers, checked against an exported pyRound when the port has one. raw (every unrounded dataclass attribute) is kept
 * for diagnosis. Skipped while lib/costing/engine.ts is not in this tree; runs as soon as the port lands.
 */
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";

import { describe, expect, it } from "vitest";

type Op = Record<string, number | string | undefined> & { name: string; sequence: number };
type Input = { quantity: number; scrap_factor: number; ops: Op[]; programming_time_hr?: number; programming_rate_per_hr?: number;
  first_article_inspection_hr?: number; margin_pct?: number } & Record<string, unknown>;
type GoldenCase = { name: string; input: Input; raw: unknown; dict: unknown };
type Golden = { source: { file: string; commit: string; sha256: string }; cases: GoldenCase[]; py_round: { x: number; n: number; out: number }[] };
type Engine = { calcDetailedQuote: (input: Input) => unknown; pyRound?: (x: number, n: number) => number };

const GOLDEN = JSON.parse(readFileSync(path.resolve(__dirname, "../fixtures/costing-golden.json"), "utf8")) as Golden;
const ENGINE_FILE = path.resolve(__dirname, "../../lib/costing/engine.ts");
const engine: Engine | null = existsSync(ENGINE_FILE) ? ((await import(/* @vite-ignore */ ENGINE_FILE)) as Engine) : null;

describe("costing golden fixtures (always)", () => {
  it("come from the real engine file and cover the branches", () => {
    expect(GOLDEN.source.file).toBe("services/costing-engine/app/services/quoting_enhanced.py");
    expect(GOLDEN.source.sha256).toMatch(/^[0-9a-f]{64}$/);
    expect(GOLDEN.cases.length).toBeGreaterThanOrEqual(30);
    const quantities = GOLDEN.cases.map((c) => c.input.quantity);
    expect(Math.min(...quantities)).toBe(1);
    expect(Math.max(...quantities)).toBe(1000);
    const some = (f: (c: GoldenCase) => boolean) => GOLDEN.cases.some(f);
    const anyOp = (key: string) => some((c) => c.input.ops.some((o) => Number(o[key] ?? 0) > 0));
    expect(some((c) => c.input.ops.length === 0)).toBe(true);
    expect(some((c) => c.input.ops.length >= 4)).toBe(true);
    expect(some((c) => (c.input.programming_time_hr ?? 0) > 0)).toBe(true);
    expect(some((c) => (c.input.first_article_inspection_hr ?? 0) > 0)).toBe(true);
    expect(some((c) => c.input.programming_rate_per_hr === undefined)).toBe(true);
    expect(some((c) => c.input.margin_pct === undefined)).toBe(true);
    expect(some((c) => c.input.margin_pct === 0)).toBe(true);
    expect(some((c) => c.input.scrap_factor === 0) && some((c) => c.input.scrap_factor >= 0.3)).toBe(true);
    for (const key of ["tool_cost_per_part", "tool_change_time_min", "inspection_time_min", "consumables_cost_per_part"]) expect(anyOp(key)).toBe(true);
    expect(some((c) => c.input.ops.some((o) => o.operation_type === undefined))).toBe(true);
    expect(GOLDEN.py_round.length).toBeGreaterThan(100);
  });
});

describe.skipIf(!engine)("lib/costing/engine.ts matches the Python engine", () => {
  it.each(GOLDEN.cases.map((c) => [c.name, c] as const))("%s", (_name, c) => {
    expect(engine!.calcDetailedQuote(structuredClone(c.input))).toEqual(c.dict);
  });

  it.skipIf(typeof engine?.pyRound !== "function").each(GOLDEN.py_round.map((r, i) => [i, r] as const))("pyRound case %i", (_i, r) => {
    expect(Object.is(engine!.pyRound!(r.x, r.n), r.out)).toBe(true);
  });
});
